// Drzewo przedziałowe (suma): przypisanie w punkcie, suma na przedziale [l, r], indeksy 0..n-1.
// Użycie: SegTree st(n);  albo  SegTree st(a);   st.update(i, v);   st.query(l, r);
// Złożoność: budowa O(n), update i query O(log n), pamięć O(4n).
struct SegTree {
    int n;
    vector<long long> t;

    SegTree(int n) : n(n), t(4 * max(n, 1), 0) {}
    SegTree(const vector<long long>& a) : SegTree((int)a.size()) {
        if (n > 0) build(1, 0, n - 1, a);
    }
    void build(int v, int tl, int tr, const vector<long long>& a) {
        if (tl == tr) { t[v] = a[tl]; return; }
        int tm = (tl + tr) / 2;
        build(2 * v, tl, tm, a);
        build(2 * v + 1, tm + 1, tr, a);
        t[v] = t[2 * v] + t[2 * v + 1];
    }
    void update(int v, int tl, int tr, int pos, long long val) {
        if (tl == tr) { t[v] = val; return; }
        int tm = (tl + tr) / 2;
        if (pos <= tm) update(2 * v, tl, tm, pos, val);
        else update(2 * v + 1, tm + 1, tr, pos, val);
        t[v] = t[2 * v] + t[2 * v + 1];
    }
    long long query(int v, int tl, int tr, int l, int r) const {
        if (r < tl || tr < l) return 0;                  // rozłączne: element neutralny
        if (l <= tl && tr <= r) return t[v];
        int tm = (tl + tr) / 2;
        return query(2 * v, tl, tm, l, r) + query(2 * v + 1, tm + 1, tr, l, r);
    }
    void update(int pos, long long val) { update(1, 0, n - 1, pos, val); }      // a[pos] = val
    long long query(int l, int r) const { return query(1, 0, n - 1, l, r); }   // suma a[l..r]
};

// Drzewo przedziałowe (minimum), iteracyjne: przypisanie w punkcie, minimum na [l, r] (domknięty), indeksy 0..n-1.
// Użycie: SegTreeMin st(a);  st.update(i, v);  st.query(l, r);   (maksimum: min -> max, INF -> LLONG_MIN)
// Złożoność: budowa O(n), update i query O(log n), pamięć 2n.
struct SegTreeMin {
    static constexpr long long INF = LLONG_MAX;
    int n;
    vector<long long> t;

    SegTreeMin(int n) : n(n), t(2 * n, INF) {}
    SegTreeMin(const vector<long long>& a) : SegTreeMin((int)a.size()) {
        for (int i = 0; i < n; i++) t[n + i] = a[i];
        for (int i = n - 1; i > 0; i--) t[i] = min(t[2 * i], t[2 * i + 1]);
    }
    void update(int pos, long long val) {          // a[pos] = val
        pos += n;
        t[pos] = val;
        for (pos /= 2; pos >= 1; pos /= 2) t[pos] = min(t[2 * pos], t[2 * pos + 1]);
    }
    long long query(int l, int r) const {          // min a[l..r]
        long long res = INF;
        for (l += n, r += n + 1; l < r; l /= 2, r /= 2) {
            if (l & 1) res = min(res, t[l++]);
            if (r & 1) res = min(res, t[--r]);
        }
        return res;
    }
};

// Drzewo przedziałowe z leniwą propagacją: dodawanie na [l, r] i suma na [l, r], indeksy 0..n-1.
// Użycie: LazySegTree st(n);  albo  LazySegTree st(a);   st.add(l, r, v);   st.query(l, r);
// Złożoność: O(log n) na operację, pamięć O(4n).
struct LazySegTree {
    int n;
    vector<long long> sum, lazy;   // lazy[v] = dodatek czekający na zepchnięcie do dzieci v

    LazySegTree(int n) : n(n), sum(4 * max(n, 1), 0), lazy(4 * max(n, 1), 0) {}
    LazySegTree(const vector<long long>& a) : LazySegTree((int)a.size()) {
        if (n > 0) build(1, 0, n - 1, a);
    }
    void build(int v, int tl, int tr, const vector<long long>& a) {
        if (tl == tr) { sum[v] = a[tl]; return; }
        int tm = (tl + tr) / 2;
        build(2 * v, tl, tm, a);
        build(2 * v + 1, tm + 1, tr, a);
        sum[v] = sum[2 * v] + sum[2 * v + 1];
    }
    void apply(int v, int tl, int tr, long long val) {
        sum[v] += val * (tr - tl + 1);
        lazy[v] += val;
    }
    void push(int v, int tl, int tr) {
        if (lazy[v] != 0) {
            int tm = (tl + tr) / 2;
            apply(2 * v, tl, tm, lazy[v]);
            apply(2 * v + 1, tm + 1, tr, lazy[v]);
            lazy[v] = 0;
        }
    }
    void add(int v, int tl, int tr, int l, int r, long long val) {
        if (r < tl || tr < l) return;
        if (l <= tl && tr <= r) { apply(v, tl, tr, val); return; }
        push(v, tl, tr);
        int tm = (tl + tr) / 2;
        add(2 * v, tl, tm, l, r, val);
        add(2 * v + 1, tm + 1, tr, l, r, val);
        sum[v] = sum[2 * v] + sum[2 * v + 1];
    }
    long long query(int v, int tl, int tr, int l, int r) {
        if (r < tl || tr < l) return 0;
        if (l <= tl && tr <= r) return sum[v];
        push(v, tl, tr);
        int tm = (tl + tr) / 2;
        return query(2 * v, tl, tm, l, r) + query(2 * v + 1, tm + 1, tr, l, r);
    }
    void add(int l, int r, long long val) { add(1, 0, n - 1, l, r, val); }    // a[l..r] += val
    long long query(int l, int r) { return query(1, 0, n - 1, l, r); }        // suma a[l..r]
};

// Drzewo Fenwicka (BIT): dodawanie w punkcie i suma prefiksu/przedziału, indeksy 1..n.
// Użycie: Fenwick fw(n);  fw.add(i, v);  fw.sum(i);  fw.sum(l, r);  fw.kth(k)  (kth: wartości nieujemne)
// Złożoność: O(log n) na operację, pamięć O(n).
struct Fenwick {
    int n;
    vector<long long> t;

    Fenwick(int n) : n(n), t(n + 1, 0) {}
    void add(int i, long long v) {                 // a[i] += v, 1 <= i <= n
        for (; i <= n; i += i & -i) t[i] += v;
    }
    long long sum(int i) const {                   // a[1] + ... + a[i]
        long long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }
    long long sum(int l, int r) const {            // a[l] + ... + a[r]
        return l > r ? 0 : sum(r) - sum(l - 1);
    }
    int kth(long long k) const {                   // najmniejsze i z sum(i) >= k; n + 1, gdy brak
        int pos = 0, step = 1;
        while (step * 2 <= n) step *= 2;
        for (; step > 0; step /= 2)
            if (pos + step <= n && t[pos + step] < k) {
                pos += step;
                k -= t[pos];
            }
        return pos + 1;
    }
};

// Fenwick 2D: dodawanie w polu (x, y) i suma prostokąta, indeksy 1..n x 1..m.
// Użycie: Fenwick2D fw(n, m);  fw.add(x, y, v);  fw.sum(x1, y1, x2, y2);
// Złożoność: O(log n · log m) na operację, pamięć O(n·m).
struct Fenwick2D {
    int n, m;
    vector<vector<long long>> t;

    Fenwick2D(int n, int m) : n(n), m(m), t(n + 1, vector<long long>(m + 1, 0)) {}
    void add(int x, int y, long long v) {
        for (int i = x; i <= n; i += i & -i)
            for (int j = y; j <= m; j += j & -j) t[i][j] += v;
    }
    long long sum(int x, int y) const {              // prostokąt [1..x] x [1..y]
        long long s = 0;
        for (int i = x; i > 0; i -= i & -i)
            for (int j = y; j > 0; j -= j & -j) s += t[i][j];
        return s;
    }
    long long sum(int x1, int y1, int x2, int y2) const {
        if (x1 > x2 || y1 > y2) return 0;
        return sum(x2, y2) - sum(x1 - 1, y2) - sum(x2, y1 - 1) + sum(x1 - 1, y1 - 1);
    }
};

// Sparse table: minimum na [l, r] w O(1) dla tablicy bez zmian, indeksy 0..n-1.
// Użycie: SparseTable st(a);  st.query(l, r);    (max / gcd: zamień min w dwóch miejscach)
// Złożoność: budowa O(n log n), zapytanie O(1), pamięć O(n log n).
template <class T>
struct SparseTable {
    vector<vector<T>> st;   // st[k][i] = min(a[i .. i + 2^k - 1])

    SparseTable(const vector<T>& a) {
        int n = a.size();
        int levels = __lg(max(n, 1)) + 1;
        st.assign(levels, vector<T>(n));
        st[0] = a;
        for (int k = 1; k < levels; k++)
            for (int i = 0; i + (1 << k) <= n; i++)
                st[k][i] = min(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
    }
    T query(int l, int r) const {                    // l <= r
        int k = __lg(r - l + 1);
        return min(st[k][l], st[k][r - (1 << k) + 1]);
    }
};

// DSU (Find & Union): kompresja ścieżek + łączenie według rozmiaru, elementy 0..n-1.
// Użycie: DSU dsu(n);  dsu.unite(a, b);  dsu.same(a, b);  dsu.size(a);  dsu.components
// Złożoność: O(α(n)) zamortyzowanie na operację (praktycznie stała).
struct DSU {
    vector<int> parent, sz;
    int components;

    DSU(int n) : parent(n), sz(n, 1), components(n) { iota(parent.begin(), parent.end(), 0); }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];   // połowienie ścieżki
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {               // false, gdy już były w jednym zbiorze
        a = find(a), b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
        components--;
        return true;
    }
    bool same(int a, int b) { return find(a) == find(b); }
    int size(int x) { return sz[find(x)]; }
};

// Binsearch po wyniku: najmniejsze x z [lo, hi], dla którego check(x) == true.
// Wymaga: check monotoniczny (false...false true...true) i check(hi) == true.
// Złożoność: O(log(hi - lo) · koszt check).
auto check = [&](long long x) -> bool {
    return x * x >= 1000;                  // tu warunek z zadania
};
long long lo = 0, hi = 1000000000;
while (lo < hi) {
    long long mid = lo + (hi - lo) / 2;
    if (check(mid)) hi = mid;
    else lo = mid + 1;
}
// lo = najmniejsza odpowiedź

// Ręczne lower_bound / upper_bound na posortowanym (niemalejąco) wektorze; zwracają indeks, n gdy brak.
// lowerBound: pierwszy i z a[i] >= x;  upperBound: pierwszy i z a[i] > x;  liczba x = upper - lower.
// Złożoność: O(log n).
template <class T>
int lowerBound(const vector<T>& a, const type_identity_t<T>& x) {
    int lo = 0, hi = a.size();           // odpowiedź zawsze w [lo, hi]
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] >= x) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}
template <class T>
int upperBound(const vector<T>& a, const type_identity_t<T>& x) {
    int lo = 0, hi = a.size();
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] > x) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

// BFS: najkrótsze odległości (liczba krawędzi) od start; -1 = nieosiągalny.
// Użycie: vector<vector<int>> adj(n);  ...  vector<int> dist = bfs(adj, s);
// Złożoność: O(n + m).
vector<int> bfs(const vector<vector<int>>& adj, int start) {
    vector<int> dist(adj.size(), -1);
    queue<int> q;
    dist[start] = 0;
    q.push(start);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int u : adj[v])
            if (dist[u] == -1) {
                dist[u] = dist[v] + 1;
                q.push(u);
            }
    }
    return dist;
}

// BFS na planszy: odległości od (sr, sc) po polach różnych od '#', ruch w 4 kierunkach; -1 = nieosiągalne.
// Użycie: vector<string> grid(n);  ...  auto dist = bfsGrid(grid, sr, sc);   dist[r][c]
// Złożoność: O(n·m).
vector<vector<int>> bfsGrid(const vector<string>& grid, int sr, int sc) {
    static const int dr[4] = {-1, 0, 1, 0}, dc[4] = {0, 1, 0, -1};
    int n = grid.size(), m = grid[0].size();
    vector<vector<int>> dist(n, vector<int>(m, -1));
    queue<pair<int, int>> q;
    dist[sr][sc] = 0;
    q.push({sr, sc});
    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
            if (grid[nr][nc] == '#' || dist[nr][nc] != -1) continue;
            dist[nr][nc] = dist[r][c] + 1;
            q.push({nr, nc});
        }
    }
    return dist;
}

// DFS: odwiedza wszystkie wierzchołki osiągalne z v (visited[u] = true).
// Użycie: vector<bool> visited(n, false);  dfs(start, adj, visited);
//         liczba składowych: for (v) if (!visited[v]) { dfs(v, adj, visited); comps++; }
// Złożoność: O(n + m); głębokość rekurencji do n (uwaga na stos przy bardzo długich ścieżkach).
void dfs(int v, const vector<vector<int>>& adj, vector<bool>& visited) {
    visited[v] = true;
    for (int u : adj[v])
        if (!visited[u]) dfs(u, adj, visited);
}

// Dijkstra: najkrótsze odległości od src przy NIEUJEMNYCH wagach; nieosiągalne: dist[v] == LLONG_MAX.
// Użycie: vector<vector<pair<int, long long>>> adj(n);  adj[a].push_back({b, w});  auto dist = dijkstra(adj, s);
// Złożoność: O((n + m) log m).
vector<long long> dijkstra(const vector<vector<pair<int, long long>>>& adj, int src) {
    vector<long long> dist(adj.size(), LLONG_MAX);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;   // (odległość, wierzchołek)
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, v] = pq.top();
        pq.pop();
        if (d != dist[v]) continue;           // nieaktualny wpis — v już przetworzony
        for (auto [u, w] : adj[v])
            if (d + w < dist[u]) {
                dist[u] = d + w;
                pq.push({dist[u], u});
            }
    }
    return dist;
}

// Bellman–Ford: najkrótsze ścieżki od src, wagi mogą być ujemne. Krawędzie skierowane (a, b, w).
// Zwraca false, gdy z src osiągalny jest ujemny cykl. Nieosiągalne: dist[v] == LLONG_MAX.
// Użycie: vector<long long> dist;  bool ok = bellmanFord(n, edges, s, dist);
// Złożoność: O(n·m).
bool bellmanFord(int n, const vector<tuple<int, int, long long>>& edges, int src, vector<long long>& dist) {
    dist.assign(n, LLONG_MAX);
    dist[src] = 0;
    for (int round = 0; round < n - 1; round++) {
        bool changed = false;
        for (auto [a, b, w] : edges)
            if (dist[a] != LLONG_MAX && dist[a] + w < dist[b]) {
                dist[b] = dist[a] + w;
                changed = true;
            }
        if (!changed) break;
    }
    for (auto [a, b, w] : edges)
        if (dist[a] != LLONG_MAX && dist[a] + w < dist[b]) return false;   // dalej się poprawia — ujemny cykl
    return true;
}

// Floyd–Warshall: najkrótsze ścieżki między wszystkimi parami.
// Wejście: d[i][j] = waga krawędzi i->j (LLONG_MAX = brak), d[i][i] = 0. Po wywołaniu d[i][j] = odległość.
// d[i][i] < 0 po wywołaniu oznacza ujemny cykl przez i.
// Złożoność: O(n^3).
void floydWarshall(vector<vector<long long>>& d) {
    int n = d.size();
    for (int k = 0; k < n; k++)
        for (int i = 0; i < n; i++) {
            if (d[i][k] == LLONG_MAX) continue;
            for (int j = 0; j < n; j++)
                if (d[k][j] != LLONG_MAX && d[i][k] + d[k][j] < d[i][j]) d[i][j] = d[i][k] + d[k][j];
        }
}

// Sortowanie topologiczne (Kahn): kolejność wierzchołków 0..n-1 taka, że każda krawędź v->u idzie w przód.
// Jeśli wynik ma mniej niż n elementów, graf ma cykl. Leksykograficznie najmniejsza: priority_queue z greater.
// Użycie: vector<int> order = topoSort(adj);  bool hasCycle = order.size() < adj.size();
// Złożoność: O(n + m).
vector<int> topoSort(const vector<vector<int>>& adj) {
    int n = adj.size();
    vector<int> indegree(n, 0), order;
    for (int v = 0; v < n; v++)
        for (int u : adj[v]) indegree[u]++;
    queue<int> q;
    for (int v = 0; v < n; v++)
        if (indegree[v] == 0) q.push(v);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        order.push_back(v);
        for (int u : adj[v])
            if (--indegree[u] == 0) q.push(u);
    }
    return order;
}

// Silnie spójne składowe (Tarjan). comp[v] = numer składowej, count = liczba składowych.
// Numeracja w odwrotnej kolejności topologicznej: krawędź u->v między składowymi ma comp[u] > comp[v].
// Użycie: TarjanSCC scc(adj);  scc.comp[v];  scc.count
// Złożoność: O(n + m); rekurencja do głębokości n.
struct TarjanSCC {
    int n, timer = 0, count = 0;
    vector<int> tin, low, comp, stk;
    vector<bool> onStack;

    TarjanSCC(const vector<vector<int>>& adj)
        : n(adj.size()), tin(n, -1), low(n, 0), comp(n, -1), onStack(n, false) {
        for (int v = 0; v < n; v++)
            if (tin[v] == -1) dfs(v, adj);
    }
    void dfs(int v, const vector<vector<int>>& adj) {
        tin[v] = low[v] = timer++;
        stk.push_back(v);
        onStack[v] = true;
        for (int u : adj[v]) {
            if (tin[u] == -1) {
                dfs(u, adj);
                low[v] = min(low[v], low[u]);
            } else if (onStack[u]) {
                low[v] = min(low[v], tin[u]);
            }
        }
        if (low[v] == tin[v]) {             // v jest korzeniem składowej
            while (true) {
                int u = stk.back();
                stk.pop_back();
                onStack[u] = false;
                comp[u] = count;
                if (u == v) break;
            }
            count++;
        }
    }
};

// Mosty i punkty artykulacji w grafie nieskierowanym (wierzchołki 0..n-1, krawędzie {a, b}); multikrawędzie OK.
// Użycie: Bridges br(n, edges);  br.bridges = numery krawędzi będących mostami;  br.isCut[v] = punkt artykulacji?
// Złożoność: O(n + m); rekurencja do głębokości n.
struct Bridges {
    int n, timer = 0;
    vector<vector<pair<int, int>>> adj;   // (sąsiad, numer krawędzi)
    vector<int> tin, low, bridges;
    vector<bool> isCut;

    Bridges(int n, const vector<pair<int, int>>& edges) : n(n), adj(n), tin(n, -1), low(n, 0), isCut(n, false) {
        for (int i = 0; i < (int)edges.size(); i++) {
            auto [a, b] = edges[i];
            adj[a].push_back({b, i});
            adj[b].push_back({a, i});
        }
        for (int v = 0; v < n; v++)
            if (tin[v] == -1) dfs(v, -1);
    }
    void dfs(int v, int parentEdge) {
        tin[v] = low[v] = timer++;
        int children = 0;
        for (auto [u, id] : adj[v]) {
            if (id == parentEdge) continue;              // nie wracamy tą samą krawędzią
            if (tin[u] != -1) {
                low[v] = min(low[v], tin[u]);            // krawędź powrotna
            } else {
                dfs(u, id);
                low[v] = min(low[v], low[u]);
                if (low[u] > tin[v]) bridges.push_back(id);
                if (parentEdge != -1 && low[u] >= tin[v]) isCut[v] = true;
                children++;
            }
        }
        if (parentEdge == -1 && children > 1) isCut[v] = true;   // korzeń DFS
    }
};

// Kruskal: waga minimalnego drzewa (lasu) rozpinającego. Krawędzie (w, a, b), wierzchołki 0..n-1.
// Graf spójny ⇔ wybrano n - 1 krawędzi (przekaż wektor usedEdges, żeby je dostać).
// Użycie: long long w = kruskal(n, edges);   albo   kruskal(n, edges, &used);
// Złożoność: O(m log m).
long long kruskal(int n, vector<tuple<long long, int, int>> edges, vector<tuple<long long, int, int>>* usedEdges = nullptr) {
    sort(edges.begin(), edges.end());
    vector<int> parent(n);
    iota(parent.begin(), parent.end(), 0);
    auto findRoot = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    long long total = 0;
    for (const auto& [w, a, b] : edges) {
        int ra = findRoot(a), rb = findRoot(b);
        if (ra == rb) continue;                 // krawędź zamknęłaby cykl
        parent[ra] = rb;
        total += w;
        if (usedEdges) usedEdges->push_back({w, a, b});
    }
    return total;
}

// Prim: waga minimalnego drzewa rozpinającego; adj[v] = {(u, w)} (graf nieskierowany — dodaj obie strony).
// Zwraca -1, gdy graf jest niespójny.
// Użycie: long long w = prim(adj);
// Złożoność: O(m log m).
long long prim(const vector<vector<pair<int, long long>>>& adj) {
    int n = adj.size();
    if (n == 0) return 0;
    vector<bool> inTree(n, false);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;   // (waga krawędzi, wierzchołek)
    pq.push({0, 0});
    long long total = 0;
    int added = 0;
    while (!pq.empty() && added < n) {
        auto [w, v] = pq.top();
        pq.pop();
        if (inTree[v]) continue;
        inTree[v] = true;
        total += w;
        added++;
        for (auto [u, wu] : adj[v])
            if (!inTree[u]) pq.push({wu, u});
    }
    return added == n ? total : -1;
}

// LCA (binary lifting) dla drzewa o wierzchołkach 0..n-1, adj = lista sąsiedztwa (krawędzie w obie strony).
// Użycie: LCA lca(adj, root);  lca.lca(u, v);  lca.dist(u, v);  lca.kthAncestor(v, k);  lca.depth[v]
// Złożoność: budowa O(n log n), zapytanie O(log n).
struct LCA {
    int n, LOG;
    vector<vector<int>> up;     // up[j][v] = przodek v o 2^j poziomów wyżej (korzeń wskazuje na siebie)
    vector<int> depth;

    LCA(const vector<vector<int>>& adj, int root) : n(adj.size()) {
        LOG = 1;
        while ((1 << LOG) < n) LOG++;
        up.assign(LOG, vector<int>(n, root));
        depth.assign(n, 0);
        vector<int> order = {root};          // BFS — bez ryzyka przepełnienia stosu
        vector<bool> seen(n, false);
        seen[root] = true;
        for (size_t i = 0; i < order.size(); i++) {
            int v = order[i];
            for (int u : adj[v])
                if (!seen[u]) {
                    seen[u] = true;
                    depth[u] = depth[v] + 1;
                    up[0][u] = v;
                    order.push_back(u);
                }
        }
        for (int j = 1; j < LOG; j++)
            for (int v = 0; v < n; v++) up[j][v] = up[j - 1][up[j - 1][v]];
    }
    int kthAncestor(int v, int k) const {    // k <= depth[v]
        for (int j = 0; j < LOG; j++)
            if ((k >> j) & 1) v = up[j][v];
        return v;
    }
    int lca(int a, int b) const {
        if (depth[a] < depth[b]) swap(a, b);
        a = kthAncestor(a, depth[a] - depth[b]);
        if (a == b) return a;
        for (int j = LOG - 1; j >= 0; j--)
            if (up[j][a] != up[j][b]) {
                a = up[j][a];
                b = up[j][b];
            }
        return up[0][a];
    }
    int dist(int a, int b) const { return depth[a] + depth[b] - 2 * depth[lca(a, b)]; }
};

// Dinic: maksymalny przepływ, wierzchołki 0..n-1. Po maxFlow: level[v] != -1 ⇔ v po stronie s w min. przekroju.
// Użycie: Dinic flow(n);  flow.addEdge(a, b, cap);  long long f = flow.maxFlow(s, t);
// Krawędź nieskierowana: addEdge(a, b, c) i addEdge(b, a, c).
// Złożoność: O(V^2 E) ogólnie, O(E sqrt V) dla grafów dwudzielnych z przepustowościami 1.
struct Dinic {
    struct Edge {
        int to;
        long long cap;
    };
    int n;
    vector<Edge> edges;             // krawędź i oraz i ^ 1 to para (prosta, odwrotna)
    vector<vector<int>> adj;
    vector<int> level, ptr;

    Dinic(int n) : n(n), adj(n), level(n), ptr(n) {}
    void addEdge(int a, int b, long long cap) {
        adj[a].push_back(edges.size());
        edges.push_back({b, cap});
        adj[b].push_back(edges.size());
        edges.push_back({a, 0});
    }
    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        level[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int id : adj[v])
                if (edges[id].cap > 0 && level[edges[id].to] == -1) {
                    level[edges[id].to] = level[v] + 1;
                    q.push(edges[id].to);
                }
        }
        return level[t] != -1;
    }
    long long dfs(int v, int t, long long pushed) {
        if (v == t || pushed == 0) return pushed;
        for (int& i = ptr[v]; i < (int)adj[v].size(); i++) {
            int id = adj[v][i], u = edges[id].to;
            if (level[u] != level[v] + 1 || edges[id].cap == 0) continue;
            long long got = dfs(u, t, min(pushed, edges[id].cap));
            if (got > 0) {
                edges[id].cap -= got;
                edges[id ^ 1].cap += got;
                return got;
            }
        }
        return 0;
    }
    long long maxFlow(int s, int t) {
        long long flow = 0;
        while (bfs(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);
            while (long long pushed = dfs(s, t, LLONG_MAX)) flow += pushed;
        }
        return flow;
    }
};

// Maksymalne skojarzenie w grafie dwudzielnym (Kuhn). Lewa strona 0..n-1, prawa 0..m-1.
// Użycie: Kuhn k(n, m);  k.addEdge(l, r);  int size = k.maxMatching();  k.matchLeft[l], k.matchRight[r] (-1 = wolny)
// Złożoność: O(n · E); w praktyce szybko (przetasowanie list sąsiedztwa dodatkowo pomaga).
struct Kuhn {
    int n, m, stamp = 0;
    vector<vector<int>> adj;
    vector<int> matchLeft, matchRight, visited;

    Kuhn(int n, int m) : n(n), m(m), adj(n), matchLeft(n, -1), matchRight(m, -1), visited(n, 0) {}
    void addEdge(int l, int r) { adj[l].push_back(r); }
    bool tryAugment(int v) {
        if (visited[v] == stamp) return false;
        visited[v] = stamp;
        for (int r : adj[v])
            if (matchRight[r] == -1 || tryAugment(matchRight[r])) {
                matchRight[r] = v;
                matchLeft[v] = r;
                return true;
            }
        return false;
    }
    int maxMatching() {
        int result = 0;
        for (int v = 0; v < n; v++) {
            if (matchLeft[v] != -1) { result++; continue; }
            stamp++;
            if (tryAugment(v)) result++;
        }
        return result;
    }
};

// KMP: pi[i] = długość najdłuższego właściwego prefiksu s[0..i], który jest też jego sufiksem.
// kmpSearch zwraca pozycje (0-indeksowane) wszystkich wystąpień wzorca w tekście.
// Użycie: auto pi = prefixFunction(s);  auto pos = kmpSearch(text, pattern);
// Złożoność: O(|text| + |pattern|).
vector<int> prefixFunction(const string& s) {
    int n = s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; i++) {
        int k = pi[i - 1];
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];
        if (s[i] == s[k]) k++;
        pi[i] = k;
    }
    return pi;
}
vector<int> kmpSearch(const string& text, const string& pattern) {
    vector<int> result;
    if (pattern.empty()) return result;
    vector<int> pi = prefixFunction(pattern);
    int k = 0;
    for (int i = 0; i < (int)text.size(); i++) {
        while (k > 0 && text[i] != pattern[k]) k = pi[k - 1];
        if (text[i] == pattern[k]) k++;
        if (k == (int)pattern.size()) {
            result.push_back(i - k + 1);
            k = pi[k - 1];
        }
    }
    return result;
}

// Funkcja Z: z[i] = długość najdłuższego wspólnego prefiksu s i s[i..]; z[0] = n.
// Wyszukiwanie: z = zFunction(p + '#' + t) ('#' spoza alfabetu), wystąpienie na pozycji i - |p| - 1, gdy z[i] == |p|.
// Złożoność: O(n).
vector<int> zFunction(const string& s) {
    int n = s.size();
    vector<int> z(n, 0);
    if (n > 0) z[0] = n;
    for (int i = 1, l = 0, r = 0; i < n; i++) {          // [l, r) = najdalej sięgający znany „z-blok”
        if (i < r) z[i] = min(r - i, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] > r) {
            l = i;
            r = i + z[i];
        }
    }
    return z;
}

// Hashowanie napisów: dwa moduły + losowa podstawa (ta sama dla wszystkich obiektów StringHash).
// get(l, r) = hash podsłowa s[l..r) (r wyłącznie) zakodowany jako jedna liczba long long.
// Użycie: StringHash h(s);  if (h.get(a, a + len) == h.get(b, b + len)) ...
// Złożoność: budowa O(n), zapytanie O(1).
struct StringHash {
    static constexpr long long MOD1 = 1000000007, MOD2 = 998244353;
    vector<long long> h1, h2, p1, p2;

    StringHash(const string& s) {
        static const long long BASE = 100000 + mt19937(chrono::steady_clock::now().time_since_epoch().count())() % 900000000;
        int n = s.size();
        h1.assign(n + 1, 0); h2.assign(n + 1, 0);
        p1.assign(n + 1, 1); p2.assign(n + 1, 1);
        for (int i = 0; i < n; i++) {
            long long c = (unsigned char)s[i] + 1;          // znak nigdy nie ma wartości 0
            h1[i + 1] = (h1[i] * BASE + c) % MOD1;
            h2[i + 1] = (h2[i] * BASE + c) % MOD2;
            p1[i + 1] = p1[i] * BASE % MOD1;
            p2[i + 1] = p2[i] * BASE % MOD2;
        }
    }
    long long get(int l, int r) const {
        long long x1 = (h1[r] - h1[l] * p1[r - l] % MOD1 + MOD1) % MOD1;
        long long x2 = (h2[r] - h2[l] * p2[r - l] % MOD2 + MOD2) % MOD2;
        return x1 * MOD2 + x2;
    }
};

// Trie na literach 'a'..'z': wstawianie, liczba słów z prefiksem, liczba wystąpień słowa.
// Użycie: Trie tr;  tr.insert(w);  tr.countPrefix(p);  tr.countWord(w);
// Złożoność: O(|s|) na operację, pamięć ~104 B na węzeł.
struct Trie {
    vector<array<int, 26>> next;   // 0 = brak syna (korzeń to węzeł 0)
    vector<int> passCount, endCount;

    Trie() { newNode(); }
    int newNode() {
        next.push_back({});
        passCount.push_back(0);
        endCount.push_back(0);
        return (int)next.size() - 1;
    }
    void insert(const string& s) {
        int v = 0;
        passCount[0]++;
        for (char ch : s) {
            int c = ch - 'a';
            if (next[v][c] == 0) {
                int u = newNode();          // najpierw tworzymy węzeł (wektor może się przenieść)
                next[v][c] = u;
            }
            v = next[v][c];
            passCount[v]++;
        }
        endCount[v]++;
    }
    int findNode(const string& s) const {
        int v = 0;
        for (char ch : s) {
            v = next[v][ch - 'a'];
            if (v == 0) return -1;
        }
        return v;
    }
    int countPrefix(const string& p) const { int v = findNode(p); return v == -1 ? 0 : passCount[v]; }
    int countWord(const string& w) const { int v = findNode(w); return v == -1 ? 0 : endCount[v]; }
};

// Manacher: d1[i] = liczba palindromów nieparzystych o środku i (s[i-d1+1 .. i+d1-1] jest palindromem),
//           d2[i] = liczba palindromów parzystych o środku między i-1 a i (s[i-d2 .. i+d2-1]).
// Najdłuższy palindrom: max po i z (2*d1[i] - 1) i (2*d2[i]). Liczba podsłów-palindromów: suma d1 + suma d2.
// Złożoność: O(n).
pair<vector<int>, vector<int>> manacher(const string& s) {
    int n = s.size();
    vector<int> d1(n), d2(n);
    for (int i = 0, l = 0, r = -1; i < n; i++) {
        int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);
        while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) k++;
        d1[i] = k--;
        if (i + k > r) { l = i - k; r = i + k; }
    }
    for (int i = 0, l = 0, r = -1; i < n; i++) {
        int k = (i > r) ? 0 : min(d2[l + r - i + 1], r - i + 1);
        while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k]) k++;
        d2[i] = k--;
        if (i + k > r) { l = i - k - 1; r = i + k; }
    }
    return {d1, d2};
}

// Sito Eratostenesa: isPrime[i] dla i w [0, n] i lista liczb pierwszych <= n.
// Użycie: vector<int> primes;  vector<bool> isPrime = sieve(n, primes);
// Złożoność: O(n log log n), pamięć O(n).
vector<bool> sieve(int n, vector<int>& primes) {
    vector<bool> isPrime(n + 1, true);
    isPrime[0] = false;
    if (n >= 1) isPrime[1] = false;
    for (long long i = 2; i * i <= n; i++)
        if (isPrime[i])
            for (long long j = i * i; j <= n; j += i) isPrime[j] = false;
    primes.clear();
    for (int i = 2; i <= n; i++)
        if (isPrime[i]) primes.push_back(i);
    return isPrime;
}

// Sito najmniejszych dzielników pierwszych (spf) + rozkład na czynniki w O(log x).
// Użycie: SmallestPrimeFactor sp(1000000);  auto f = sp.factorize(x);  // pary (p, wykładnik) rosnąco, 1 <= x <= n
// Złożoność: budowa O(n log log n), rozkład O(log x), pamięć O(n).
struct SmallestPrimeFactor {
    vector<int> spf;               // spf[x] = najmniejszy dzielnik pierwszy x (x >= 2)

    SmallestPrimeFactor(int n) : spf(n + 1, 0) {
        for (int i = 2; i <= n; i++)
            if (spf[i] == 0)       // i jest pierwsza
                for (int j = i; j <= n; j += i)
                    if (spf[j] == 0) spf[j] = i;
    }
    vector<pair<int, int>> factorize(int x) const {
        vector<pair<int, int>> factors;
        while (x > 1) {
            int p = spf[x], e = 0;
            while (x % p == 0) {
                x /= p;
                e++;
            }
            factors.push_back({p, e});
        }
        return factors;
    }
};

// Szybkie potęgowanie: base^exp mod m, exp >= 0, 1 <= m <= ~3·10^9 (iloczyn dwóch reszt mieści się w long long).
// Użycie: power(2, 10, 1000000007) == 1024;  odwrotność dla m pierwszego: power(a, m - 2, m)
// Złożoność: O(log exp).
long long power(long long base, long long exp, long long mod) {
    long long result = 1 % mod;
    base %= mod;
    if (base < 0) base += mod;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

// Odwrotność modularna: x z (a * x) % m == 1, rozszerzony Euklides (m nie musi być pierwsze).
// Zwraca -1, gdy gcd(a, m) != 1. Dla m pierwszego to samo da power(a, m - 2, m).
// Złożoność: O(log m).
long long modInverse(long long a, long long m) {
    a %= m;
    if (a < 0) a += m;
    long long oldR = a, r = m, oldS = 1, s = 0;       // niezmiennik: oldR ≡ oldS·a, r ≡ s·a (mod m)
    while (r != 0) {
        long long q = oldR / r, tmp;
        tmp = oldR - q * r; oldR = r; r = tmp;
        tmp = oldS - q * s; oldS = s; s = tmp;
    }
    if (oldR != 1) return -1;                         // a i m nie są względnie pierwsze
    oldS %= m;
    if (oldS < 0) oldS += m;
    return oldS;
}

// Silnie i odwrotności silni modulo liczba pierwsza MOD; C(n, k) w O(1). Wymaga N < MOD.
// Użycie: Binomial bin(1000000);  bin.C(n, k);  bin.fact[n];  bin.invFact[n]
// Złożoność: budowa O(N + log MOD), zapytanie O(1).
struct Binomial {
    static constexpr long long MOD = 1000000007;
    vector<long long> fact, invFact;

    static long long power(long long b, long long e) {
        long long r = 1;
        b %= MOD;
        while (e > 0) {
            if (e & 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return r;
    }
    Binomial(int N) : fact(N + 1), invFact(N + 1) {
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N] = power(fact[N], MOD - 2);              // małe twierdzenie Fermata
        for (int i = N; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;
    }
    long long C(int n, int k) const {                     // 0, gdy k < 0 lub k > n
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }
};

// Rozszerzony Euklides: zwraca g = gcd(a, b) i ustawia x, y tak, że a*x + b*y = g (a, b >= 0).
// Równanie a*x + b*y = c ma rozwiązanie ⇔ g | c; wtedy (x·c/g, y·c/g) jest jednym z nich.
// Złożoność: O(log min(a, b)), rekurencja głębokości O(log).
long long extGcd(long long a, long long b, long long& x, long long& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long x1, y1;
    long long g = extGcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

// Macierze modulo mod: mnożenie i szybkie potęgowanie (wyrazy mod ograniczone przez ~3·10^9).
// Użycie: Matrix M = {{1, 1}, {1, 0}};  Matrix R = matPow(M, n, MOD);   // R[0][1] = F(n)
// Złożoność: mnożenie O(k^3), potęgowanie O(k^3 log e).
using Matrix = vector<vector<long long>>;

Matrix matMul(const Matrix& A, const Matrix& B, long long mod) {
    int n = A.size(), inner = B.size(), m = B[0].size();
    Matrix C(n, vector<long long>(m, 0));
    for (int i = 0; i < n; i++)
        for (int k = 0; k < inner; k++) {
            if (A[i][k] == 0) continue;
            for (int j = 0; j < m; j++) C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod;
        }
    return C;
}
Matrix matPow(Matrix base, long long exp, long long mod) {
    int n = base.size();
    Matrix result(n, vector<long long>(n, 0));
    for (int i = 0; i < n; i++) result[i][i] = 1 % mod;   // macierz jednostkowa
    while (exp > 0) {
        if (exp & 1) result = matMul(result, base, mod);
        base = matMul(base, base, mod);
        exp >>= 1;
    }
    return result;
}

// NWD i NWW (Euklides) dla long long; wynik nieujemny. W C++17 są też std::gcd / std::lcm z <numeric>.
// lcmLL dzieli przed mnożeniem: a / gcd(a, b) * b (wynik musi mieścić się w long long).
// Złożoność: O(log min(a, b)).
long long gcdLL(long long a, long long b) {
    a = llabs(a);
    b = llabs(b);
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}
long long lcmLL(long long a, long long b) {
    if (a == 0 || b == 0) return 0;
    return llabs(a) / gcdLL(a, b) * llabs(b);
}

// Otoczka wypukła (monotone chain / Andrew): wierzchołki przeciwnie do ruchu wskazówek zegara,
// zaczynając od najmniejszego (x, y); punkty współliniowe na bokach są pomijane.
// Użycie: vector<pair<long long, long long>> hull = convexHull(points);
// Złożoność: O(n log n).
vector<pair<long long, long long>> convexHull(vector<pair<long long, long long>> pts) {
    sort(pts.begin(), pts.end());
    pts.erase(unique(pts.begin(), pts.end()), pts.end());
    int n = pts.size();
    if (n <= 2) return pts;
    auto cross = [](const pair<long long, long long>& o, const pair<long long, long long>& a,
                    const pair<long long, long long>& b) {
        return (a.first - o.first) * (b.second - o.second) - (a.second - o.second) * (b.first - o.first);
    };
    vector<pair<long long, long long>> hull(2 * n);
    int k = 0;
    for (int i = 0; i < n; i++) {                          // dolna otoczka
        while (k >= 2 && cross(hull[k - 2], hull[k - 1], pts[i]) <= 0) k--;
        hull[k++] = pts[i];
    }
    for (int i = n - 2, lower = k + 1; i >= 0; i--) {      // górna otoczka
        while (k >= lower && cross(hull[k - 2], hull[k - 1], pts[i]) <= 0) k--;
        hull[k++] = pts[i];
    }
    hull.resize(k - 1);                                    // ostatni punkt powtarza pierwszy
    return hull;
}

// Geometria na liczbach całkowitych (long long): punkt/wektor, iloczyn wektorowy i skalarny, orientacja, odcinki.
// cross(a, b) > 0 ⇔ b jest na lewo od a (obrót przeciwny do ruchu wskazówek zegara).
// Użycie: Point a{0, 0}, b{3, 1};  long long c = cross(b - a, p - a);  orientation(a, b, p);  segmentsIntersect(a, b, c, d);
// Złożoność: O(1); współrzędne do ~10^9 (iloczyny do ~4·10^18).
struct Point {
    long long x, y;
    Point operator+(const Point& o) const { return {x + o.x, y + o.y}; }
    Point operator-(const Point& o) const { return {x - o.x, y - o.y}; }
    Point operator*(long long k) const { return {x * k, y * k}; }
    bool operator==(const Point& o) const { return x == o.x && y == o.y; }
    bool operator<(const Point& o) const { return x != o.x ? x < o.x : y < o.y; }
};
long long cross(const Point& a, const Point& b) { return a.x * b.y - a.y * b.x; }
long long dot(const Point& a, const Point& b) { return a.x * b.x + a.y * b.y; }
long long norm2(const Point& a) { return dot(a, a); }                 // kwadrat długości
int orientation(const Point& a, const Point& b, const Point& c) {     // 1 = w lewo, -1 = w prawo, 0 = współliniowe
    long long v = cross(b - a, c - a);
    return (v > 0) - (v < 0);
}
bool onSegment(const Point& a, const Point& b, const Point& p) {      // p na odcinku [a, b]
    return cross(b - a, p - a) == 0 && min(a.x, b.x) <= p.x && p.x <= max(a.x, b.x) &&
           min(a.y, b.y) <= p.y && p.y <= max(a.y, b.y);
}
bool segmentsIntersect(const Point& a, const Point& b, const Point& c, const Point& d) {   // wspólny punkt?
    int o1 = orientation(a, b, c), o2 = orientation(a, b, d);
    int o3 = orientation(c, d, a), o4 = orientation(c, d, b);
    if (o1 * o2 < 0 && o3 * o4 < 0) return true;                      // przecięcie „na krzyż”
    return onSegment(a, b, c) || onSegment(a, b, d) || onSegment(c, d, a) || onSegment(c, d, b);
}

// Algorytm Mo: odpowiedzi offline na zapytania o przedziały [l, r] (0-indeksowane, domknięte).
// add(i) / remove(i) — dodanie / usunięcie pozycji i z bieżącego przedziału; answer() — wynik dla bieżącego przedziału.
// Użycie: auto res = moSolve(n, queries, [&](int i) {...}, [&](int i) {...}, [&]() { return wynik; });
// Złożoność: O((n + q) · sqrt(n)) wywołań add/remove (muszą być O(1) — liczniki w tablicy, nie w map).
template <class Add, class Remove, class Answer>
auto moSolve(int n, const vector<pair<int, int>>& queries, Add add, Remove remove, Answer answer) {
    int q = queries.size();
    int block = max(1, (int)(n / sqrt(max(q, 1))));
    vector<int> order(q);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        int ba = queries[a].first / block, bb = queries[b].first / block;
        if (ba != bb) return ba < bb;
        return (ba & 1) ? queries[a].second > queries[b].second : queries[a].second < queries[b].second;
    });
    vector<decltype(answer())> result(q);
    int curL = 0, curR = -1;                       // pusty przedział
    for (int idx : order) {
        auto [l, r] = queries[idx];
        while (curL > l) add(--curL);               // najpierw rozszerzamy...
        while (curR < r) add(++curR);
        while (curL < l) remove(curL++);            // ...potem zwężamy
        while (curR > r) remove(curR--);
        result[idx] = answer();
    }
    return result;
}

// Convex hull trick (monotoniczny): minimum z prostych y = k*x + b.
// Proste dodawaj z NIEROSNĄCYMI k (maksimum: wstaw (-k, -b) i zaneguj wynik). Zapytania w dowolnej kolejności.
// Użycie: MonotoneCHT cht;  cht.addLine(k, b);  long long best = cht.query(x);   (query wymaga >= 1 prostej)
// Złożoność: addLine O(1) zamortyzowanie, query O(log n).
struct MonotoneCHT {
    struct Line {
        long long k, b;
        long long eval(long long x) const { return k * x + b; }
    };
    vector<Line> hull;

    // m jest zbędna między l i r (k_l > k_m > k_r), gdy przecięcie l z r nie leży na prawo od przecięcia l z m
    static bool useless(const Line& l, const Line& m, const Line& r) {
        return (__int128)(r.b - l.b) * (l.k - m.k) <= (__int128)(m.b - l.b) * (l.k - r.k);
    }
    void addLine(long long k, long long b) {
        Line nw{k, b};
        if (!hull.empty() && hull.back().k == k) {         // równe nachylenie: zostaje mniejsze b
            if (hull.back().b <= b) return;
            hull.pop_back();
        }
        while (hull.size() >= 2 && useless(hull[hull.size() - 2], hull.back(), nw)) hull.pop_back();
        hull.push_back(nw);
    }
    long long query(long long x) const {
        int lo = 0, hi = (int)hull.size() - 1;
        while (lo < hi) {                                  // wartości na otoczce są „unimodalne” względem indeksu
            int mid = (lo + hi) / 2;
            if (hull[mid].eval(x) >= hull[mid + 1].eval(x)) lo = mid + 1;
            else hi = mid;
        }
        return hull[lo].eval(x);
    }
};

// Li Chao tree: minimum z prostych y = k*x + b w punkcie x z [lo, hi]; proste w dowolnej kolejności.
// Użycie: LiChao lc(-1e9, 1e9);  lc.addLine(k, b);  long long v = lc.query(x);   (query wymaga >= 1 prostej)
// Maksimum: addLine(-k, -b) i -query(x). Uwaga na przepełnienie k*x + b.
// Złożoność: O(log(hi - lo)) na operację, pamięć O(liczba prostych).
struct LiChao {
    struct Line {
        long long k, b;
        long long eval(long long x) const { return k * x + b; }
    };
    struct Node {
        Line line;
        int left = -1, right = -1;
    };
    vector<Node> t;
    long long lo, hi;

    LiChao(long long lo, long long hi) : lo(lo), hi(hi) {}
    void addLine(long long k, long long b) {
        Line nw{k, b};
        if (t.empty()) { t.push_back({nw}); return; }
        int v = 0;
        long long l = lo, r = hi;
        while (true) {
            long long m = l + (r - l) / 2;
            bool betterLeft = nw.eval(l) < t[v].line.eval(l);
            bool betterMid = nw.eval(m) < t[v].line.eval(m);
            if (betterMid) swap(t[v].line, nw);            // w węźle zostaje prosta lepsza w środku
            if (l == r) return;
            if (betterLeft != betterMid) {                 // przegrana może wygrać tylko w [l, m]
                if (t[v].left == -1) { t[v].left = t.size(); t.push_back({nw}); return; }
                v = t[v].left;
                r = m;
            } else {                                       // ... albo tylko w (m, r]
                if (t[v].right == -1) { t[v].right = t.size(); t.push_back({nw}); return; }
                v = t[v].right;
                l = m + 1;
            }
        }
    }
    long long query(long long x) const {
        long long res = LLONG_MAX;
        int v = 0;
        long long l = lo, r = hi;
        while (v != -1) {
            res = min(res, t[v].line.eval(x));
            long long m = l + (r - l) / 2;
            if (x <= m) { v = t[v].left; r = m; }
            else { v = t[v].right; l = m + 1; }
        }
        return res;
    }
};

// Ordered set z pb_ds (tylko g++/libstdc++): set + k-ty element + ranga.
// s.find_by_order(k) — iterator na k-ty najmniejszy (od 0) albo end();  s.order_of_key(x) — ile elementów < x.
// Multizbiór: ordered_set<pair<T, int>> z unikalnym drugim elementem.  Złożoność: O(log n) na operację.
#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>

template <class T>
using ordered_set = __gnu_pbds::tree<T, __gnu_pbds::null_type, less<T>, __gnu_pbds::rb_tree_tag,
                                     __gnu_pbds::tree_order_statistics_node_update>;

// Generator losowy mt19937_64 (ziarno z zegara) i losowanie liczby z przedziału [l, r].
// Użycie: long long x = randInt(1, 6);  shuffle(v.begin(), v.end(), rng);   (stałe ziarno do powtarzalnych testów: rng.seed(123))
// Złożoność: O(1) na losowanie.
mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

long long randInt(long long l, long long r) {
    return uniform_int_distribution<long long>(l, r)(rng);
}

