// Kompresja współrzędnych: id[i] w 0..k-1 z zachowaniem porządku; vals[id[i]] == a[i] (vals posortowane, bez powtórzeń).
// Użycie: vector<long long> vals;  vector<int> id = compress(a, vals);
//         numer dowolnej wartości x: lower_bound(vals.begin(), vals.end(), x) - vals.begin()
// Złożoność: O(n log n).
template <class T>
vector<int> compress(const vector<T>& a, vector<T>& vals) {
    vals = a;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    vector<int> id(a.size());
    for (size_t i = 0; i < a.size(); i++)
        id[i] = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin();
    return id;
}

// Sumy prefiksowe 2D: suma prostokąta [x1..x2] x [y1..y2] w O(1); indeksy 0-indeksowane, przedziały domknięte.
// Użycie: Prefix2D ps(grid);  long long s = ps.sum(x1, y1, x2, y2);    grid = vector<vector<long long>>
// Złożoność: budowa O(n·m), zapytanie O(1), pamięć O(n·m).
struct Prefix2D {
    vector<vector<long long>> P;   // P[i][j] = suma grid[0..i-1][0..j-1]

    Prefix2D(const vector<vector<long long>>& g) {
        int n = g.size(), m = n ? g[0].size() : 0;
        P.assign(n + 1, vector<long long>(m + 1, 0));
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                P[i + 1][j + 1] = g[i][j] + P[i][j + 1] + P[i + 1][j] - P[i][j];
    }
    long long sum(int x1, int y1, int x2, int y2) const {
        if (x1 > x2 || y1 > y2) return 0;
        return P[x2 + 1][y2 + 1] - P[x1][y2 + 1] - P[x2 + 1][y1] + P[x1][y1];
    }
};

// Najdłuższy ŚCIŚLE rosnący podciąg w O(n log n); zwraca indeksy jego elementów (rosnąco).
// Długość = wynik.size(). Niemalejący: zamień lower_bound na upper_bound.
// Użycie: vector<int> idx = longestIncreasingSubsequence(a);
// Złożoność: O(n log n).
vector<int> longestIncreasingSubsequence(const vector<long long>& a) {
    int n = a.size();
    vector<long long> tails;       // tails[len - 1] = najmniejszy możliwy ostatni element podciągu długości len
    vector<int> tailIdx, parent(n, -1);
    for (int i = 0; i < n; i++) {
        int pos = lower_bound(tails.begin(), tails.end(), a[i]) - tails.begin();
        if (pos == (int)tails.size()) {
            tails.push_back(a[i]);
            tailIdx.push_back(i);
        } else {
            tails[pos] = a[i];
            tailIdx[pos] = i;
        }
        parent[i] = pos > 0 ? tailIdx[pos - 1] : -1;   // poprzednik w odtworzeniu
    }
    vector<int> result;
    for (int i = tailIdx.empty() ? -1 : tailIdx.back(); i != -1; i = parent[i]) result.push_back(i);
    reverse(result.begin(), result.end());
    return result;
}

// Plecak 0/1: maksymalna wartość przedmiotów o łącznej wadze <= W (każdy przedmiot najwyżej raz).
// Pojemność przeglądana MALEJĄCO — przy rosnącej dostalibyśmy plecak nieograniczony.
// Użycie: long long best = knapsack01(weight, value, W);
// Złożoność: O(n·W) czasu, O(W) pamięci.
long long knapsack01(const vector<int>& weight, const vector<long long>& value, int W) {
    vector<long long> dp(W + 1, 0);   // dp[c] = najlepsza wartość przy wadze <= c
    for (size_t i = 0; i < weight.size(); i++)
        for (int c = W; c >= weight[i]; c--)
            dp[c] = max(dp[c], dp[c - weight[i]] + value[i]);
    return dp[W];
}

// Wszystkie maski n bitów i ich niepuste podmaski (malejąco): sub = (sub - 1) & mask.
// Pusta podmaska (sub = 0) nie jest odwiedzana — obsłuż osobno, jeśli trzeba.
// Złożoność: O(3^n) dla wszystkich masek łącznie (n <= ~16).
int n = 4;
for (int mask = 0; mask < (1 << n); mask++) {
    for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
        // sub — niepusta podmaska mask; dopełnienie w mask: mask ^ sub
    }
}

// Stos monotoniczny: nextGreater[i] = indeks najbliższego elementu > a[i] po prawej (n, gdy brak),
//                    previousSmaller[i] = indeks najbliższego elementu < a[i] po lewej (-1, gdy brak).
// Inne warianty: zmień nierówność (>= / <=) albo kierunek pętli.
// Złożoność: O(n) — każdy indeks raz wchodzi i raz wychodzi ze stosu.
vector<int> nextGreater(const vector<long long>& a) {
    int n = a.size();
    vector<int> res(n, n), st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.back()] < a[i]) {
            res[st.back()] = i;
            st.pop_back();
        }
        st.push_back(i);
    }
    return res;
}
vector<int> previousSmaller(const vector<long long>& a) {
    int n = a.size();
    vector<int> res(n, -1), st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.back()] >= a[i]) st.pop_back();
        res[i] = st.empty() ? -1 : st.back();
        st.push_back(i);
    }
    return res;
}

// Kolejka monotoniczna: kolejka FIFO z minimum w O(1) zamortyzowanie (maksimum: odwróć porównanie w push).
// Użycie: MonotonicQueue q;  q.push(x);  q.pop();  q.getMin();  q.size()
//         minimum w oknie długości k: push(a[i]); if (q.size() > k) q.pop(); if (i >= k - 1) wynik = q.getMin();
// Złożoność: O(1) zamortyzowanie na operację.
struct MonotonicQueue {
    deque<pair<long long, long long>> dq;   // (wartość, numer wstawienia), wartości rosną od przodu
    long long pushed = 0, popped = 0;

    void push(long long x) {
        while (!dq.empty() && dq.back().first >= x) dq.pop_back();   // gorsi kandydaci nigdy nie będą minimum
        dq.push_back({x, pushed++});
    }
    void pop() {                                   // usuwa najstarszy element (kolejka niepusta)
        if (!dq.empty() && dq.front().second == popped) dq.pop_front();
        popped++;
    }
    long long getMin() const { return dq.front().first; }   // kolejka niepusta
    long long size() const { return pushed - popped; }
    bool empty() const { return pushed == popped; }
};

// Treap (multizbiór) na split/merge: insert, eraseOne, kth (k od 1), countLess. Węzeł 0 = pusty.
// Użycie: Treap tr;  tr.insert(x);  tr.eraseOne(x);  tr.kth(k);  tr.countLess(x);  tr.size()
// Złożoność: O(log n) oczekiwanie na operację.
struct Treap {
    struct Node {
        int key;
        unsigned prio;
        int size, left, right;
    };
    vector<Node> t;
    int root = 0;
    mt19937 rng{712367};

    Treap() { t.push_back({0, 0, 0, 0, 0}); }
    int sz(int v) const { return t[v].size; }
    void pull(int v) { t[v].size = 1 + sz(t[v].left) + sz(t[v].right); }
    void split(int v, int key, int& l, int& r) {          // l: klucze < key, r: klucze >= key
        if (v == 0) { l = r = 0; return; }
        if (t[v].key < key) { split(t[v].right, key, t[v].right, r); l = v; }
        else { split(t[v].left, key, l, t[v].left); r = v; }
        pull(v);
    }
    int merge(int l, int r) {                             // klucze l <= klucze r
        if (l == 0 || r == 0) return l ? l : r;
        if (t[l].prio > t[r].prio) { t[l].right = merge(t[l].right, r); pull(l); return l; }
        t[r].left = merge(l, t[r].left);
        pull(r);
        return r;
    }
    void insert(int key) {
        t.push_back({key, (unsigned)rng(), 1, 0, 0});
        int node = (int)t.size() - 1, a, b;
        split(root, key, a, b);
        root = merge(merge(a, node), b);
    }
    void eraseOne(int key) {                              // usuwa jedną kopię key, jeśli jest
        int a, b, c;
        split(root, key, a, b);
        split(b, key + 1, b, c);
        if (b) b = merge(t[b].left, t[b].right);
        root = merge(merge(a, b), c);
    }
    int kth(int k) const {                                // k-ty najmniejszy (k od 1); -1, gdy k > size
        int v = root;
        while (v) {
            int leftSize = sz(t[v].left);
            if (k <= leftSize) v = t[v].left;
            else if (k == leftSize + 1) return t[v].key;
            else { k -= leftSize + 1; v = t[v].right; }
        }
        return -1;
    }
    int countLess(int key) const {                        // ile kluczy < key
        int v = root, res = 0;
        while (v) {
            if (t[v].key < key) { res += sz(t[v].left) + 1; v = t[v].right; }
            else v = t[v].left;
        }
        return res;
    }
    int size() const { return sz(root); }
};

// Hash odporny na anty-testy dla unordered_map / unordered_set z kluczami całkowitymi (i parami int).
// Użycie: unordered_map<long long, int, custom_hash> mp;   unordered_set<pair<int, int>, pair_hash> st;
//         mp.reserve(n) — mniej przehashowań.
// Złożoność: O(1) średnio na operację.
struct custom_hash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }
    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + FIXED_RANDOM);
    }
};
struct pair_hash {
    size_t operator()(const pair<int, int>& p) const {
        static const custom_hash h;
        return h(((uint64_t)(uint32_t)p.first << 32) | (uint32_t)p.second);
    }
};

// __int128: zamiana na napis, wypisywanie i wczytywanie (cin/cout nie obsługują tego typu). Zakres ok. ±1,7·10^38.
// Użycie: __int128 x = readInt128();  printInt128(x * x);  string s = int128ToString(x);
// Złożoność: O(liczba cyfr).
string int128ToString(__int128 x) {
    if (x == 0) return "0";
    bool negative = x < 0;
    unsigned __int128 u = negative ? -(unsigned __int128)x : (unsigned __int128)x;
    string s;
    while (u > 0) {
        s += char('0' + (int)(u % 10));
        u /= 10;
    }
    if (negative) s += '-';
    reverse(s.begin(), s.end());
    return s;
}
void printInt128(__int128 x) { cout << int128ToString(x); }
__int128 readInt128() {                       // liczba dziesiętna z opcjonalnym znakiem
    string s;
    cin >> s;
    size_t i = (s[0] == '-' || s[0] == '+') ? 1 : 0;
    __int128 x = 0;
    for (; i < s.size(); i++) x = x * 10 + (s[i] - '0');
    return s[0] == '-' ? -x : x;
}

// Kierunki na planszy: dx = zmiana wiersza, dy = zmiana kolumny. 4 kierunki: góra, prawo, dół, lewo; 8 — z przekątnymi.
// Użycie: for (int d = 0; d < 4; d++) { int nr = r + dx[d], nc = c + dy[d]; if (inside(nr, nc, n, m)) ... }
// Obrót w prawo: d = (d + 1) % 4, w lewo: d = (d + 3) % 4.
// Złożoność: O(1).
const int dx[4] = {-1, 0, 1, 0};
const int dy[4] = {0, 1, 0, -1};
const int dx8[8] = {-1, -1, 0, 1, 1, 1, 0, -1};
const int dy8[8] = {0, 1, 1, 1, 0, -1, -1, -1};

bool inside(int r, int c, int n, int m) { return r >= 0 && r < n && c >= 0 && c < m; }
